#include "csl_finalize.h"
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Private zero-width markers identify joins generated by the stylesheet. */
#define BOUNDARY ((CeCslFinalSpanKind)99)
#define GENERATED ((CeCslFinalSpanKind)100)
typedef union Block {
    long double alignment;
    void *pointer;
    unsigned char padding[32];
    struct { size_t size; } value;
} Block;
struct CeCslFinalized {
    CeCslOutputAllocator user, allocator;
    const CeCslEvaluation *evaluation;
    const CeCslEvalNode *omit_names;
    const CeCslEvalNode *first_names;
    CeCslInline *names_key;
    size_t source_cite_index;
    bool joined;
    CeCslInline *text;
    CeCslOutput *output;
    CeCslFinalSpan *spans;
    size_t count, capacity, live;
    bool limit, missing_term;
    char *error;
    size_t error_capacity;
};
static void *normal_alloc(void *context, size_t size) { (void)context; return malloc(size); }
static void normal_free(void *context, void *p) { (void)context; free(p); }
static bool fail(CeCslFinalized *r, const char *message) {
    if (r->error && r->error_capacity) snprintf(r->error, r->error_capacity, "CSL finalization: %s", message);
    return false;
}
static void *budget_alloc(void *context, size_t size) {
    CeCslFinalized *r = context;
    if (size > CE_CSL_FINALIZE_MAX_WORKSPACE - sizeof(Block) ||
        r->live > CE_CSL_FINALIZE_MAX_WORKSPACE - sizeof(Block) - size) {
        r->limit = true; return NULL;
    }
    Block *block = r->user.allocate(r->user.context, sizeof(Block) + size);
    if (!block) return NULL;
    block->value.size = sizeof(Block) + size;
    r->live += block->value.size;
    return block + 1;
}
static void budget_free(void *context, void *p) {
    if (!p) return;
    CeCslFinalized *r = context;
    Block *block = (Block *)p - 1;
    r->live -= block->value.size;
    r->user.deallocate(r->user.context, block);
}
static size_t text_size(const CeCslInline *text) {
    size_t size = 0; (void)ce_csl_inline_text(text, &size); return size;
}
static bool plain(CeCslFinalized *r, const char *text, unsigned format, CeCslInline **out) {
    CeCslOutput *ir = ce_csl_output_new(&r->allocator, r->error, r->error_capacity);
    if (!ir) return false;
    bool ok = ce_csl_output_append(ir, text ? text : "", text ? strlen(text) : 0,
        format, NULL, r->error, r->error_capacity) &&
        ce_csl_inline_from_output(ir, false, &r->allocator, out, r->error, r->error_capacity);
    ce_csl_output_free(ir); return ok;
}
static bool append_plain(CeCslFinalized *r, CeCslInline *target, const char *text, unsigned format) {
    if (!text || !*text) return true;
    CeCslInline *part = NULL;
    bool ok = plain(r, text, format, &part) &&
        ce_csl_inline_concat(target, part, r->error, r->error_capacity);
    ce_csl_inline_free(part); return ok;
}
static bool span(CeCslFinalized *r, const CeCslEvalNode *node, CeCslFinalSpanKind kind,
    size_t offset, size_t length, size_t person, CeCslEvalDisplay display) {
    if (r->count == CE_CSL_FINALIZE_MAX_SPANS) return fail(r, "span limit exceeded");
    if (r->count == r->capacity) {
        size_t capacity = r->capacity ? r->capacity * 2 : 32;
        if (capacity > CE_CSL_FINALIZE_MAX_SPANS) capacity = CE_CSL_FINALIZE_MAX_SPANS;
        CeCslFinalSpan *next = budget_alloc(r, capacity * sizeof(*next));
        if (!next) return fail(r, "out of memory for spans");
        if (r->count) memcpy(next, r->spans, r->count * sizeof(*next));
        budget_free(r, r->spans); r->spans = next; r->capacity = capacity;
    }
    r->spans[r->count++] = (CeCslFinalSpan){node, kind, offset, length, person, display, r->source_cite_index};
    return true;
}
static bool boundary(CeCslFinalized *r, const CeCslEvalNode *node, size_t offset) {
    return span(r, node, BOUNDARY, offset, 0, SIZE_MAX, CE_CSL_EVAL_DISPLAY_NONE);
}
static bool append_generated(CeCslFinalized *r, const CeCslEvalNode *node,
    CeCslInline *target, const char *text, unsigned format) {
    size_t before = text_size(target);
    if (!append_plain(r, target, text, format)) return false;
    size_t after = text_size(target);
    return before == after || span(r, node, GENERATED, before, after - before,
        SIZE_MAX, CE_CSL_EVAL_DISPLAY_NONE);
}
static void shift(CeCslFinalized *r, size_t begin, size_t end, size_t offset) {
    for (size_t i = begin; i < end; ++i) r->spans[i].offset += offset;
}
static bool transform(CeCslFinalized *r, CeCslInline **body, size_t begin,
    bool strip, CeCslTextCase mode) {
    CeCslInlineMap map = {0};
    bool ok = strip ? ce_csl_inline_strip_periods(*body, &r->allocator, body, &map,
        r->error, r->error_capacity) : ce_csl_inline_case(*body, mode,
        ce_csl_evaluation_item_language(r->evaluation),
        ce_csl_evaluation_default_locale(r->evaluation), &r->allocator, body, &map,
        r->error, r->error_capacity);
    if (ok) for (size_t i = begin; i < r->count; ++i) {
        CeCslFinalSpan *s = &r->spans[i];
        if (!ce_csl_inline_map_range(&map, s->offset, s->length, &s->offset, &s->length)) {
            ok = fail(r, "invalid scalar span during text transformation"); break;
        }
    }
    ce_csl_inline_map_free(&map); return ok;
}
static bool materialize(CeCslFinalized *r, const CeCslEvalNode *node, size_t depth,
    size_t quote_depth, CeCslInline **out, bool *rendered_variable, bool *suffix_success) {
    *rendered_variable = false;
    *suffix_success = false;
    if (depth > CE_CSL_EVALUATE_MAX_DEPTH) return fail(r, "tree depth limit exceeded");
    const CeCslEvalNodeInfo *info = ce_csl_eval_node_info(node);
    if (!info) return fail(r, "missing evaluation node");
    const CeCslEvalDecoration *d = &info->decoration;
    size_t begin = r->count;
    CeCslInline *body = NULL, *wrapped = NULL;
    if (node == r->omit_names) return plain(r, "", 0, out);
    *suffix_success = info->year_suffix_call_succeeded;
    /* A chosen branch is transparent even when its only executed output is an
     * empty year-suffix. Empty group/macro/name boundaries remain opaque. */
    if (!info->nonempty && info->kind != CE_CSL_EVAL_CHOOSE) return plain(r, "", 0, out);
    const CeCslInline *content = ce_csl_eval_node_content(node);
    bool ok = content ? ce_csl_inline_clone(content, &r->allocator, &body, r->error, r->error_capacity) :
        plain(r, "", 0, &body);
    if (!ok) goto done;
    if (content) {
        *rendered_variable = info->rendered_variable_present;
        const CeCslNamesResult *names = ce_csl_eval_node_names(node);
        for (size_t i = 0; i < ce_csl_names_result_person_count(names); ++i) {
            const CeCslNameRendered *person = ce_csl_names_result_person(names, i);
            if (!person || person->output_offset > text_size(body) ||
                person->output_length > text_size(body) - person->output_offset) {
                ok = fail(r, "invalid rendered person span"); goto done;
            }
            if (!span(r, node, CE_CSL_FINAL_PERSON, person->output_offset,
                person->output_length, i, CE_CSL_EVAL_DISPLAY_NONE)) { ok = false; goto done; }
        }
    } else {
        bool prior = false;
        const char *delimiter = info->kind == CE_CSL_EVAL_LAYOUT || info->kind == CE_CSL_EVAL_MACRO ? "" : d->delimiter;
        for (const CeCslEvalNode *child = info->first_child; child; child = ce_csl_eval_node_info(child)->next) {
            size_t child_begin = r->count;
            CeCslInline *part = NULL;
            bool child_rendered = false, child_suffix = false;
            ok = materialize(r, child, depth + 1, quote_depth + (d->quotes ? 1 : 0), &part,
                &child_rendered, &child_suffix);
            if (ok) *suffix_success |= child_suffix;
            if (ok && text_size(part)) {
                CeCslEvalKind kind = ce_csl_eval_node_info(child)->kind;
                *rendered_variable |= child_rendered || kind == CE_CSL_EVAL_GROUP || kind == CE_CSL_EVAL_MACRO;
                size_t child_end = r->count;
                if (prior) {
                    ok = boundary(r, node, text_size(body)) &&
                        append_generated(r, node, body, delimiter, d->effective_format) &&
                        boundary(r, node, text_size(body));
                }
                /* Boundaries just added already use parent coordinates. */
                if (ok) {
                    shift(r, child_begin, child_end, text_size(body));
                    ok = ce_csl_inline_concat(body, part, r->error, r->error_capacity);
                }
                prior = true;
            }
            ce_csl_inline_free(part);
            if (!ok) goto done;
        }
    }
    if (info->kind == CE_CSL_EVAL_GROUP && info->variable_called && !*rendered_variable && !*suffix_success) {
        r->count = begin;
        ok = plain(r, "", 0, &body);
        if (!ok) goto done;
    }
    if (d->strip_periods && !transform(r, &body, begin, true, CE_CSL_CASE_NONE)) { ok = false; goto done; }
    if (d->text_case != CE_CSL_CASE_NONE && !transform(r, &body, begin, false, d->text_case)) { ok = false; goto done; }
    if (!text_size(body)) {
        *rendered_variable = false;
        if (info->kind == CE_CSL_EVAL_GROUP || info->kind == CE_CSL_EVAL_MACRO || info->kind == CE_CSL_EVAL_NAMES)
            *suffix_success = false;
        r->count = begin; *out = body; body = NULL; goto done;
    }
    if (!plain(r, "", 0, &wrapped)) { ok = false; goto done; }
    unsigned affix_format = info->kind == CE_CSL_EVAL_LAYOUT ? d->effective_format : d->inherited_format;
    size_t child_end = r->count;
    if (!d->cluster_envelope && !append_generated(r, node, wrapped, d->prefix, affix_format)) { ok = false; goto done; }
    CeCslLocaleTerm open = {0}, close = {0};
    if (d->quotes) {
        const CeCslLocale *locale = ce_csl_evaluation_locale(r->evaluation);
        open = ce_csl_locale_term(locale, quote_depth % 2 ? "open-inner-quote" : "open-quote",
            CE_CSL_LOCALE_LONG, false, CE_CSL_LOCALE_NEUTER);
        close = ce_csl_locale_term(locale, quote_depth % 2 ? "close-inner-quote" : "close-quote",
            CE_CSL_LOCALE_LONG, false, CE_CSL_LOCALE_NEUTER);
        r->missing_term |= !open.found || !close.found;
    }
    if (text_size(wrapped) && !boundary(r, node, text_size(wrapped))) { ok = false; goto done; }
    if (d->quotes) {
        size_t start = text_size(wrapped);
        if (!append_plain(r, wrapped, open.text, d->effective_format) ||
            !span(r, node, CE_CSL_FINAL_OPEN_QUOTE, start, open.length, SIZE_MAX, CE_CSL_EVAL_DISPLAY_NONE)) { ok = false; goto done; }
    }
    shift(r, begin, child_end, text_size(wrapped));
    if (!ce_csl_inline_concat(wrapped, body, r->error, r->error_capacity)) { ok = false; goto done; }
    if (d->quotes) {
        size_t start = text_size(wrapped);
        if (!append_plain(r, wrapped, close.text, d->effective_format) ||
            !span(r, node, CE_CSL_FINAL_CLOSE_QUOTE, start, close.length, SIZE_MAX, CE_CSL_EVAL_DISPLAY_NONE)) { ok = false; goto done; }
    }
    if (!d->cluster_envelope && d->suffix && *d->suffix &&
        (!boundary(r, node, text_size(wrapped)) || !append_generated(r, node, wrapped, d->suffix, affix_format))) { ok = false; goto done; }
    if (!span(r, node, CE_CSL_FINAL_NODE, 0, text_size(wrapped), SIZE_MAX, d->display)) { ok = false; goto done; }
    *out = wrapped; wrapped = NULL;
done:
    ce_csl_inline_free(body); ce_csl_inline_free(wrapped); return ok;
}

typedef struct Edit { size_t start, end; bool move; } Edit;
typedef struct Range { size_t low, high; } Range;
static int compare_edit(const void *left, const void *right) {
    const Edit *a = left, *b = right;
    if (a->start != b->start) return a->start < b->start ? -1 : 1;
    return a->end < b->end ? -1 : a->end != b->end;
}
static Range combine(Range a, Range b) {
    return (Range){a.low < b.low ? a.low : b.low, a.high > b.high ? a.high : b.high};
}
static Range query(const Range *tree, size_t base, size_t start, size_t end) {
    Range result = {SIZE_MAX, 0};
    for (start += base, end += base; start < end; start /= 2, end /= 2) {
        if (start & 1) result = combine(result, tree[start++]);
        if (end & 1) result = combine(result, tree[--end]);
    }
    return result;
}
static bool copy_range(CeCslFinalized *r, CeCslInline *target, const CeCslInline *source,
    size_t start, size_t end, Range *leaves) {
    size_t offset = text_size(target);
    if (start != end) {
        CeCslInline *part = NULL;
        bool ok = ce_csl_inline_slice(source, start, end - start, &r->allocator, &part,
            r->error, r->error_capacity) && ce_csl_inline_concat(target, part, r->error, r->error_capacity);
        ce_csl_inline_free(part); if (!ok) return false;
    }
    for (size_t i = start; i < end; ++i) leaves[i] = (Range){offset + i - start, offset + i - start + 1};
    return true;
}
/* Non-overlapping edits either delete one byte or move the final ASCII byte
 * before a sequence of closing quotation marks. Source bytes keep their runs.
 * An interval tree maps arbitrary nested semantic spans in O(log payload). */
static bool apply_edits(CeCslFinalized *r, Edit *edits, size_t count) {
    if (!count) return true;
    size_t size = text_size(r->text), base = 1;
    while (base < size + 1) base *= 2;
    Range *tree = budget_alloc(r, 2 * base * sizeof(*tree));
    CeCslInline *next = NULL;
    if (!tree || !plain(r, "", 0, &next)) { budget_free(r, tree); return fail(r, "out of memory mapping punctuation"); }
    for (size_t i = 0; i < 2 * base; ++i) tree[i] = (Range){SIZE_MAX, 0};
    Range *leaves = tree + base;
    size_t cursor = 0;
    bool ok = true;
    for (size_t i = 0; i < count && ok; ++i) {
        Edit e = edits[i];
        if (e.start < cursor || e.end > size || e.start >= e.end) { ok = fail(r, "invalid punctuation edit"); break; }
        ok = copy_range(r, next, r->text, cursor, e.start, leaves);
        if (ok && e.move) ok = copy_range(r, next, r->text, e.end - 1, e.end, leaves) &&
            copy_range(r, next, r->text, e.start, e.end - 1, leaves);
        else if (ok) {
            /* A quote edit with a duplicate trailing period keeps the quotes. */
            ok = copy_range(r, next, r->text, e.start, e.end - 1, leaves);
            leaves[e.end - 1] = (Range){text_size(next), text_size(next)};
        }
        cursor = e.end;
    }
    if (ok) ok = copy_range(r, next, r->text, cursor, size, leaves);
    if (ok) {
        leaves[size] = (Range){text_size(next), text_size(next)};
        for (size_t i = base; --i;) tree[i] = combine(tree[i * 2], tree[i * 2 + 1]);
        for (size_t i = 0; i < r->count; ++i) {
            CeCslFinalSpan *s = &r->spans[i];
            if (s->offset > size || s->length > size - s->offset) { ok = fail(r, "invalid punctuation source span"); break; }
            Range range = s->length ? query(tree, base, s->offset, s->offset + s->length) : leaves[s->offset];
            s->offset = range.low; s->length = s->length ? range.high - range.low : 0;
        }
    }
    budget_free(r, tree);
    if (ok) { ce_csl_inline_free(r->text); r->text = next; } else ce_csl_inline_free(next);
    return ok;
}
static bool duplicate(unsigned char before, unsigned char after) {
    return (before == after && strchr(".,;:!?", after)) || (after == '.' && strchr(";:?!", before));
}
static void generated_bytes(const CeCslFinalized *r, unsigned char *bytes, size_t size) {
    memset(bytes, 0, size);
    for (size_t i = 0; i < r->count; ++i) {
        const CeCslFinalSpan *s = &r->spans[i];
        if (s->kind == GENERATED && s->length) memset(bytes + s->offset, 1, s->length);
    }
}
static bool punctuation(CeCslFinalized *r) {
    if (!r->count) return true;
    Edit *edits = budget_alloc(r, r->count * sizeof(*edits));
    if (!edits) return fail(r, "out of memory for punctuation edits");
    size_t size, count = 0;
    const char *text = ce_csl_inline_text(r->text, &size);
    unsigned char *generated = budget_alloc(r, size ? size : 1);
    if (!generated) { budget_free(r, edits); return fail(r, "out of memory for punctuation origins"); }
    generated_bytes(r, generated, size);
    for (size_t i = 0; i < r->count; ++i) {
        const CeCslFinalSpan *s = &r->spans[i];
        if (s->kind == BOUNDARY && s->offset && s->offset < size) {
            bool repeated = duplicate((unsigned char)text[s->offset - 1], (unsigned char)text[s->offset]) &&
                (text[s->offset] != ',' || generated[s->offset - 1] || generated[s->offset]);
            bool spaces = text[s->offset - 1] == ' ' && text[s->offset] == ' ' &&
                generated[s->offset - 1] && generated[s->offset];
            if (repeated || spaces) edits[count++] = (Edit){s->offset, s->offset + 1, false};
        }
    }
    qsort(edits, count, sizeof(*edits), compare_edit);
    size_t unique = 0;
    for (size_t i = 0; i < count; ++i)
        if (!unique || edits[i].start != edits[unique - 1].start) edits[unique++] = edits[i];
    bool ok = apply_edits(r, edits, unique), in_quote = false;
    ce_csl_locale_option(ce_csl_evaluation_locale(r->evaluation), CE_CSL_LOCALE_PUNCTUATION_IN_QUOTE, &in_quote);
    if (ok && in_quote) {
        count = 0;
        for (size_t i = 0; i < r->count; ++i) {
            const CeCslFinalSpan *s = &r->spans[i];
            if (s->kind == CE_CSL_FINAL_CLOSE_QUOTE && s->length)
                edits[count++] = (Edit){s->offset, s->offset + s->length, false};
        }
        qsort(edits, count, sizeof(*edits), compare_edit);
        unique = 0;
        for (size_t i = 0; i < count; ++i) {
            if (unique && edits[i].start <= edits[unique - 1].end) {
                if (edits[i].end > edits[unique - 1].end) edits[unique - 1].end = edits[i].end;
            } else edits[unique++] = edits[i];
        }
        text = ce_csl_inline_text(r->text, &size); count = 0;
        generated_bytes(r, generated, size);
        for (size_t i = 0; i < unique; ++i) {
            Edit e = edits[i];
            if (e.end < size && generated[e.end] && (text[e.end] == '.' || text[e.end] == ',')) {
                e.move = !(e.start && duplicate((unsigned char)text[e.start - 1], (unsigned char)text[e.end]));
                ++e.end; edits[count++] = e;
            }
        }
        ok = apply_edits(r, edits, count);
    }
    budget_free(r, generated); budget_free(r, edits); return ok;
}
static bool capture_names(CeCslFinalized *r) {
    const CeCslFinalSpan *first = NULL;
    size_t first_index = SIZE_MAX;
    for (size_t i = 0; i < r->count; ++i) {
        const CeCslFinalSpan *s = &r->spans[i];
        if (s->kind != CE_CSL_FINAL_NODE || !s->length) continue;
        const CeCslEvalNodeInfo *info = ce_csl_eval_node_info(s->node);
        if (info->kind == CE_CSL_EVAL_NAMES && info->index < first_index) {
            first = s; first_index = info->index;
        }
    }
    if (!first) return true;
    r->first_names = first->node;
    return ce_csl_inline_slice(r->text, first->offset, first->length, &r->allocator,
        &r->names_key, r->error, r->error_capacity);
}
bool ce_csl_finalize(const CeCslEvaluation *evaluation, const CeCslOutputAllocator *allocator,
    CeCslFinalized **out, char *error, size_t capacity) {
    return ce_csl_finalize_with_options(evaluation, NULL, allocator, out, error, capacity);
}
static bool contains_names(const CeCslEvaluation *evaluation, const CeCslEvalNode *target) {
    const CeCslEvalNode *node = ce_csl_evaluation_root(evaluation);
    while (node) {
        const CeCslEvalNodeInfo *info = ce_csl_eval_node_info(node);
        if (node == target) return info->kind == CE_CSL_EVAL_NAMES;
        if (info->first_child) { node = info->first_child; continue; }
        while (node && !ce_csl_eval_node_info(node)->next) node = ce_csl_eval_node_info(node)->parent;
        if (node) node = ce_csl_eval_node_info(node)->next;
    }
    return false;
}
bool ce_csl_finalize_with_options(const CeCslEvaluation *evaluation,
    const CeCslFinalizeOptions *options, const CeCslOutputAllocator *allocator,
    CeCslFinalized **out, char *error, size_t capacity) {
    if (error && capacity) *error = 0;
    if (!evaluation || !out || (allocator && (!allocator->allocate || !allocator->deallocate)) ||
        (options && options->omit_names && !contains_names(evaluation, options->omit_names))) {
        if (error && capacity) snprintf(error, capacity, "CSL finalization: invalid arguments");
        return false;
    }
    CeCslOutputAllocator user = allocator ? *allocator : (CeCslOutputAllocator){NULL, normal_alloc, normal_free};
    CeCslFinalized *r = user.allocate(user.context, sizeof(*r));
    if (!r) { if (error && capacity) snprintf(error, capacity, "CSL finalization: out of memory"); return false; }
    memset(r, 0, sizeof(*r)); r->user = user; r->evaluation = evaluation;
    r->source_cite_index = SIZE_MAX;
    r->omit_names = options ? options->omit_names : NULL;
    r->live = sizeof(*r);
    r->allocator = (CeCslOutputAllocator){r, budget_alloc, budget_free};
    r->error = error; r->error_capacity = capacity;
    r->missing_term = ce_csl_evaluation_summary(evaluation)->missing_term;
    bool rendered_variable = false;
    bool suffix_success = false;
    bool ok = materialize(r, ce_csl_evaluation_root(evaluation), 0, 0, &r->text,
        &rendered_variable, &suffix_success) &&
        capture_names(r) && punctuation(r);
    if (ok) {
        size_t keep = 0;
        for (size_t i = 0; i < r->count; ++i)
            if (r->spans[i].kind != BOUNDARY && r->spans[i].kind != GENERATED) r->spans[keep++] = r->spans[i];
        r->count = keep;
        r->output = ce_csl_output_new(&r->allocator, error, capacity);
        ok = r->output && ce_csl_inline_to_output(r->text, r->output, error, capacity);
    }
    if (!ok) {
        if (r->limit) fail(r, "workspace limit exceeded");
        ce_csl_finalized_free(r); return false;
    }
    r->error = NULL; r->error_capacity = 0;
    CeCslFinalized *old = *out; *out = r; ce_csl_finalized_free(old); return true;
}
bool ce_csl_finalize_join(const CeCslFinalizeJoinEntry *entries, size_t count,
    const CeCslOutputAllocator *allocator, CeCslFinalized **out, char *error, size_t capacity) {
    if (error && capacity) *error = 0;
    if (!entries || !count || count > CE_CSL_INPUT_MAX_CITES || !out ||
        (allocator && (!allocator->allocate || !allocator->deallocate))) {
        if (error && capacity) snprintf(error, capacity, "CSL finalization: invalid join arguments");
        return false;
    }
    const CeCslEvalNodeInfo *layout = NULL;
    const CeCslLocale *locale = NULL;
    size_t nodes = 0;
    for (size_t i = 0; i < count; ++i) {
        const CeCslEvaluation *e = entries[i].evaluation;
        const CeCslEvalNodeInfo *info = ce_csl_eval_node_info(ce_csl_evaluation_root(e));
        const CeCslEvalSummary *summary = ce_csl_evaluation_summary(e);
        if (summary && summary->node_count > CE_CSL_FINALIZE_MAX_JOIN_NODES - nodes) {
            if (error && capacity) snprintf(error, capacity, "CSL finalization: joined node work limit exceeded");
            return false;
        }
        if (summary) nodes += summary->node_count;
        if (!e || !info || info->kind != CE_CSL_EVAL_LAYOUT || !info->decoration.cluster_envelope ||
            entries[i].source_cite_index == SIZE_MAX ||
            (entries[i].omit_names && !contains_names(e, entries[i].omit_names)) ||
            (layout && (layout->occurrence.source != info->occurrence.source ||
                        layout->decoration.effective_format != info->decoration.effective_format ||
                        locale != ce_csl_evaluation_locale(e)))) {
            if (error && capacity) snprintf(error, capacity, "CSL finalization: mismatched citation join context");
            return false;
        }
        if (!layout) { layout = info; locale = ce_csl_evaluation_locale(e); }
    }
    CeCslOutputAllocator user = allocator ? *allocator : (CeCslOutputAllocator){NULL, normal_alloc, normal_free};
    CeCslFinalized *r = user.allocate(user.context, sizeof(*r));
    if (!r) { if (error && capacity) snprintf(error, capacity, "CSL finalization: out of memory"); return false; }
    memset(r, 0, sizeof(*r)); r->user = user; r->allocator = (CeCslOutputAllocator){r, budget_alloc, budget_free};
    r->live = sizeof(*r); r->error = error; r->error_capacity = capacity; r->joined = true;
    r->source_cite_index = SIZE_MAX;
    r->evaluation = entries[0].evaluation;
    bool ok = plain(r, "", 0, &r->text), prior = false;
    unsigned format = layout->decoration.effective_format;
    const CeCslEvalNode *envelope = ce_csl_evaluation_root(entries[0].evaluation);
    for (size_t i = 0; i < count && ok; ++i) {
        const CeCslFinalizeJoinEntry *entry = &entries[i];
        r->evaluation = entry->evaluation; r->omit_names = entry->omit_names;
        r->source_cite_index = entry->source_cite_index;
        r->missing_term |= ce_csl_evaluation_summary(entry->evaluation)->missing_term;
        size_t begin = r->count;
        CeCslInline *part = NULL; bool rendered = false, suffix_success = false;
        ok = materialize(r, ce_csl_evaluation_root(entry->evaluation), 0, 0, &part, &rendered, &suffix_success);
        size_t end = r->count;
        if (ok && text_size(part)) {
            r->source_cite_index = SIZE_MAX;
            if (!prior) {
                ok = append_generated(r, envelope, r->text, layout->decoration.prefix, format);
                if (ok && text_size(r->text)) ok = boundary(r, envelope, text_size(r->text));
            } else {
                ok = boundary(r, envelope, text_size(r->text)) &&
                    append_generated(r, envelope, r->text, entry->before_delimiter, format) &&
                    boundary(r, envelope, text_size(r->text));
            }
            r->source_cite_index = entry->source_cite_index;
            if (ok && entry->prefix && *entry->prefix) ok = append_plain(r, r->text, entry->prefix, format) &&
                boundary(r, ce_csl_evaluation_root(entry->evaluation), text_size(r->text));
            if (ok) {
                shift(r, begin, end, text_size(r->text));
                ok = ce_csl_inline_concat(r->text, part, error, capacity);
            }
            if (ok && entry->suffix && *entry->suffix) ok = boundary(r, ce_csl_evaluation_root(entry->evaluation), text_size(r->text)) &&
                append_plain(r, r->text, entry->suffix, format);
            prior = true;
        }
        ce_csl_inline_free(part);
    }
    r->source_cite_index = SIZE_MAX;
    if (ok && prior) ok = boundary(r, envelope, text_size(r->text)) &&
        append_generated(r, envelope, r->text, layout->decoration.suffix, format);
    if (ok) ok = punctuation(r);
    if (ok) {
        size_t keep = 0;
        for (size_t i = 0; i < r->count; ++i)
            if (r->spans[i].kind != BOUNDARY && r->spans[i].kind != GENERATED) r->spans[keep++] = r->spans[i];
        r->count = keep;
        r->output = ce_csl_output_new(&r->allocator, error, capacity);
        ok = r->output && ce_csl_inline_to_output(r->text, r->output, error, capacity);
    }
    if (!ok) {
        if (r->limit) fail(r, "workspace limit exceeded");
        ce_csl_finalized_free(r); return false;
    }
    r->error = NULL; r->error_capacity = 0;
    CeCslFinalized *old = *out; *out = r; ce_csl_finalized_free(old); return true;
}
void ce_csl_finalized_free(CeCslFinalized *r) {
    if (!r) return;
    ce_csl_inline_free(r->text); ce_csl_inline_free(r->names_key);
    ce_csl_output_free(r->output); budget_free(r, r->spans);
    r->user.deallocate(r->user.context, r);
}
const CeCslInline *ce_csl_finalized_inline(const CeCslFinalized *r) { return r ? r->text : NULL; }
const CeCslOutput *ce_csl_finalized_output(const CeCslFinalized *r) { return r ? r->output : NULL; }
const CeCslEvaluation *ce_csl_finalized_evaluation(const CeCslFinalized *r) { return r && !r->joined ? r->evaluation : NULL; }
const CeCslEvalNode *ce_csl_finalized_first_names(const CeCslFinalized *r) { return r ? r->first_names : NULL; }
const CeCslInline *ce_csl_finalized_first_names_inline(const CeCslFinalized *r) { return r ? r->names_key : NULL; }
bool ce_csl_finalized_missing_term(const CeCslFinalized *r) { return r && r->missing_term; }
size_t ce_csl_finalized_span_count(const CeCslFinalized *r) { return r ? r->count : 0; }
const CeCslFinalSpan *ce_csl_finalized_span(const CeCslFinalized *r, size_t index) { return r && index < r->count ? &r->spans[index] : NULL; }
